using System.Windows; using System.Diagnostics; using TextBox=System.Windows.Controls.TextBox; using StackPanel=System.Windows.Controls.StackPanel; using TextBlock=System.Windows.Controls.TextBlock; using Button=System.Windows.Controls.Button; using Panel=System.Windows.Controls.Panel; using Control=System.Windows.Controls.Control; namespace CloudServer; public sealed class ServerSettingsDialog:Window { readonly TextBox listen=new(),publicUrl=new(),thumbprint=new(); public string ListenPrefix=>listen.Text.Trim(); public string PublicBaseUrl=>publicUrl.Text.Trim().TrimEnd('/'); public string CertificateThumbprint=>new string(thumbprint.Text.Where(Uri.IsHexDigit).ToArray()).ToUpperInvariant(); public ServerSettingsDialog(ServerSettings s){Title="Servereinstellungen";Width=600;Height=390;WindowStartupLocation=WindowStartupLocation.CenterOwner;var p=new StackPanel{Margin=new Thickness(30)};p.Children.Add(new TextBlock{Text="Netzwerk & HTTPS",FontSize=24,FontWeight=FontWeights.Bold});p.Children.Add(new TextBlock{Text="Die öffentliche Adresse sollte für produktiven Betrieb HTTPS verwenden. Ein TLS-Zertifikat muss in Windows für die gewählte HTTPS-Bindung eingerichtet sein.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,18)});Add(p,"Listener-Präfix (z. B. http://+:5050/ oder https://+:5051/)",listen);Add(p,"Öffentliche Basisadresse (z. B. https://cloud.example.de)",publicUrl);Add(p,"TLS-Zertifikat-Fingerabdruck (optional, für HTTPS-Prüfung)",thumbprint);listen.Text=s.ListenPrefix;publicUrl.Text=s.PublicBaseUrl;thumbprint.Text=s.CertificateThumbprint;var ok=new Button{Content="Speichern",Height=42,Margin=new Thickness(0,24,0,0)};ok.Click+=(_,__)=>{if(!Uri.TryCreate(ListenPrefix,UriKind.Absolute,out var a)||(a.Scheme!="http"&&a.Scheme!="https")){System.Windows.MessageBox.Show("Ungültiges Listener-Präfix.");return;}if(!Uri.TryCreate(PublicBaseUrl,UriKind.Absolute,out var b)||(b.Scheme!="http"&&b.Scheme!="https")){System.Windows.MessageBox.Show("Ungültige öffentliche Adresse.");return;}if(!string.IsNullOrEmpty(b.UserInfo)||!string.IsNullOrEmpty(b.Query)||!string.IsNullOrEmpty(b.Fragment)){System.Windows.MessageBox.Show("Die öffentliche Basisadresse darf keine Zugangsdaten, Abfrageparameter oder URL-Fragmente enthalten.");return;}if(b.Host=="+"||b.Host=="*"||b.Host=="0.0.0.0"||b.Host=="[::]"||b.Host=="::"){System.Windows.MessageBox.Show("Die öffentliche Basisadresse muss einen konkreten Hostnamen oder eine konkrete IP-Adresse enthalten. Wildcards sind nur beim Listener zulässig.");return;}if(!ListenPrefix.EndsWith("/")){System.Windows.MessageBox.Show("Das Listener-Präfix muss mit / enden, z. B. https://+:5051/.");return;}if(a.Scheme=="https"&&b.Scheme!="https"){System.Windows.MessageBox.Show("Bei einem HTTPS-Listener muss auch die öffentliche Basisadresse HTTPS verwenden.");return;}if(a.Scheme=="https"){if(CertificateThumbprint.Length==0){System.Windows.MessageBox.Show("Für HTTPS muss der Fingerabdruck des Serverzertifikats eingetragen werden.");return;}using var certStore=new System.Security.Cryptography.X509Certificates.X509Store(System.Security.Cryptography.X509Certificates.StoreName.My,System.Security.Cryptography.X509Certificates.StoreLocation.LocalMachine);try{certStore.Open(System.Security.Cryptography.X509Certificates.OpenFlags.ReadOnly);var cert=certStore.Certificates.Find(System.Security.Cryptography.X509Certificates.X509FindType.FindByThumbprint,CertificateThumbprint,false).OfType<System.Security.Cryptography.X509Certificates.X509Certificate2>().FirstOrDefault();if(cert==null||!cert.HasPrivateKey||cert.NotAfter<=DateTime.Now){System.Windows.MessageBox.Show("Das Zertifikat wurde im Windows-Computerkonto nicht gefunden, besitzt keinen privaten Schlüssel oder ist abgelaufen.");return;}}catch(Exception ex){System.Windows.MessageBox.Show("Zertifikat konnte nicht geprüft werden: "+ex.Message);return;}var ipport="0.0.0.0:"+a.Port;try{int RunNetsh(string args){var psi=new ProcessStartInfo("netsh",args){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden};using var proc=Process.Start(psi);if(proc==null)return -1;proc.WaitForExit();return proc.ExitCode;}var rc=RunNetsh($"http add sslcert ipport={ipport} certhash={CertificateThumbprint} appid={{A4B42B31-0F87-4A51-9D71-7D8E61E7C501}} certstorename=MY");if(rc!=0){RunNetsh($"http delete sslcert ipport={ipport}");rc=RunNetsh($"http add sslcert ipport={ipport} certhash={CertificateThumbprint} appid={{A4B42B31-0F87-4A51-9D71-7D8E61E7C501}} certstorename=MY");}if(rc!=0){System.Windows.MessageBox.Show("Das Zertifikat ist gültig, aber die HTTP.SYS-Bindung konnte nicht eingerichtet werden. Prüfen Sie, ob der Port durch eine andere Anwendung reserviert ist.","HTTPS-Konfiguration",MessageBoxButton.OK,MessageBoxImage.Warning);return;}}catch(Exception ex){System.Windows.MessageBox.Show("HTTP.SYS-Bindung fehlgeschlagen: "+ex.Message);return;}System.Windows.MessageBox.Show("Zertifikat geprüft und HTTPS-Bindung für Port "+a.Port+" eingerichtet.","HTTPS-Konfiguration",MessageBoxButton.OK,MessageBoxImage.Information);}DialogResult=true;};p.Children.Add(ok);Content=p;}static void Add(Panel p,string l,Control c){p.Children.Add(new TextBlock{Text=l,Margin=new Thickness(0,10,0,4)});c.Height=34;p.Children.Add(c);} }